    function run(uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint16 feeRate, uint256 inputAmount) public {
        require(virtualBaseTokenReserves > 0);
        require(virtualNftReserves > 0 && virtualNftReserves < 1e18);
        require(feeRate <= 5000);
        require(inputAmount > 0 && inputAmount < 1e18);

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 outputAmount = inputAmount * uint256(virtualBaseTokenReserves) / (uint256(virtualNftReserves) + inputAmount);
        assert(feeAmount == outputAmount * feeRate / 10000 && protocolFeeAmount == 0 && netOutputAmount == outputAmount - feeAmount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint128 outputAmount) public {
        require(virtualBaseTokenReserves > 0);
        require(virtualNftReserves > outputAmount && outputAmount > 0);
        require(virtualBaseTokenReserves <= 1e18 && virtualNftReserves <= 2e18);

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 den = uint256(virtualNftReserves) - uint256(outputAmount);
        uint256 exactDown = uint256(outputAmount) * uint256(virtualBaseTokenReserves) / den;

        assert(
            feeAmount == 0 &&
            protocolFeeAmount == 0 &&
            netInputAmount >= exactDown &&
            netInputAmount <= exactDown + 1
        );
    }
}

