contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(feeRate <= 5_000);
        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );
        bool reverted;
        try c.setFeeRate(5_001) { reverted = false; } catch { reverted = true; }
        assert(
            reverted &&
            c.initialized() &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == virtualBaseTokenReserves &&
            c.virtualNftReserves() == virtualNftReserves &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useStolenNftOracle &&
            c.payRoyalties() == payRoyalties
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint256 outputAmount,
        uint16 feeRate
    ) public {
        require(feeRate <= 5_000);
        require(virtualNftReserves > 0);
        require(outputAmount < virtualNftReserves);
        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);
        uint256 denominator = uint256(virtualNftReserves) - outputAmount;
        uint256 inputAmount = (outputAmount * virtualBaseTokenReserves + denominator - 1) / denominator;
        assert(
            feeAmount == inputAmount * feeRate / 10_000 &&
            netInputAmount == inputAmount + feeAmount + protocolFeeAmount &&
            netInputAmount >= inputAmount
        );
    }
    receive() external payable {}
}

